"""Unrelated metadata failure dispatcher/BIND fixtures; no benchmark/data calls."""
import json,subprocess,sys,tempfile,unittest
from pathlib import Path
import e42_evaluate as E
F=E.F
class FailureBind(unittest.TestCase):
 def env(self,**extra):return dict({'schema_version':1,'epoch':42,'kind':F.KIND,'phase':'dev'},**extra)
 def test_custody_unknown_and_exact_partial_counts(self):
  self.assertIsNone(E.custody(None)['semantic_label_decodes']);self.assertTrue(E.custody(None)['semantic_decode_count_uncertain']);r=self.env(semantic_labels_decoded=2,decode_attempted_tokens=2,semantic_decode_count_uncertain=False,late_custodian_function_calls=1,label_reader_calls=1,status='GOLD_JOIN_FAILED_FINAL_NO_RETRY');c=E.custody(r);self.assertEqual(c['semantic_label_decodes'],2);self.assertFalse(c['semantic_decode_count_uncertain']);v=E.failure_replay({'data_roles':{'dev':[]}},'a'*64,{}, {},c,[{'code':'UNRELATED_FIXTURE'}]);self.assertFalse(v['evaluation_executed']);self.assertIsNone(v['metrics']);self.assertTrue(all(x=='NOT_EVALUATED'for x in v['gate_checks'].values()))
 def test_isolated_cli_missing_join_captures_without_evaluate_or_label_read(self):
  with tempfile.TemporaryDirectory()as t:
   root=Path(t)/'project';root.mkdir();private=Path(t)/'private-custody';roles={'train':[],'dev':['synthetic:'+str(i)for i in range(12)],'calibration':[],'confirmation':[]};pr=F.put(root/'plan.json',self.env(data_roles=roles,external_custody_evidence_paths={'joined_labels':str(private/'joined_labels.json'),'gold_join_report':str(private/'GOLD_JOIN_REPORT.json')}));ps=pr['sha256'];source=F.put(root/'source.json',self.env(checks_passed=True,verified_actual_remote_readback=True,plan_sha256=ps,source_plan_sha256=ps));proof=F.put(root/'closure.json',self.env(source_plan_sha256=ps,physical_supervisor_closed=True,physical_closure_passed=True,unknown_physical_ownership=False,owned_worker_group_members=[]));dispatch=F.put(root/'dispatch.json',self.env(plan_sha256=ps));fa=F.put(root/'failure.json',self.env(source_checkpoint=F.SOURCE,source_plan_sha256=ps,root_metadata_failure_capture_authorized=True,failure_reason_code='UNRELATED_MISSING_JOIN_FIXTURE',evidence={'plan':pr,'raw':None,'execution':None,'dispatch':dispatch,'physical_closure':proof,'source_admission':source,'gold_join_report':None,'joined_labels':None}));out=root/'replay.json';script=Path(E.__file__);p=subprocess.run([sys.executable,'-I','-B',str(script),'--mode','EVALUATE','--project',str(root),'--out',str(out),'--failure-admission',fa['path'],'--expected-failure-admission-sha256',fa['sha256']],capture_output=True,text=True);self.assertEqual(p.returncode,0,p.stderr);v=json.loads(out.read_bytes());self.assertEqual(v['command_execution']['requested_mode'],'EVALUATE');self.assertEqual(v['command_execution']['evaluate_function_calls'],0);self.assertEqual(v['command_execution']['capture_failure_function_calls'],1);self.assertFalse(v['evaluation_executed']);self.assertIsNone(v['metrics']);self.assertIsNone(v['label_custody']['semantic_label_decodes']);self.assertTrue(v['label_custody']['semantic_decode_count_uncertain']);self.assertFalse(private.exists())
 def test_bind_exact_preservation_and_nested_bool_integer_mutation(self):
  with tempfile.TemporaryDirectory()as t:
   root=Path(t);v=self.env(checks_passed=False,dev_passed=False,evaluation_executed=False,source_plan_sha256='a'*64,nested={'facts':[{'flag':False,'count':1}]});vr=F.put(root/'replay.json',v);rr=F.put(root/'results.json',dict(v,publication_checkpoint={'qualification_replay':vr}));b=E.bind(vr,rr,root);self.assertTrue(b['publication_binding_checks_passed']);self.assertFalse(b['evaluated_integrity_checks_passed']);self.assertFalse(b['evaluation_executed'])
   for i,mutation in enumerate([{'facts':[{'flag':0,'count':1}]},{'facts':[{'flag':False,'count':True}]},{'facts':{'flag':False,'count':1}}]):
    r=F.put(root/f'mutation{i}.json',dict(v,nested=mutation,publication_checkpoint={'qualification_replay':vr}))
    with self.assertRaises(ValueError):E.bind(vr,r,root)
if __name__=='__main__':unittest.main()
